ORGANIZE_WORKSPACE_CACHE_NAMESPACE = "organize-workspace"

logger = logging.getLogger(__name__)


def _get_accessible_capture(user: User, capture_id: Any) -> InboxCapture:
    return get_object_or_404(
        InboxCapture.objects.filter(family_id__in=get_accessible_family_ids(user)),
        pk=capture_id,
    )


def _proposal_index_from_post(request: Any) -> int:
    try:
        return max(0, int(request.POST.get("proposal_index", "0")))
    except (TypeError, ValueError):
        return 0


def _items_from_post(request: Any) -> list[str] | None:
    items = [item.strip() for item in request.POST.getlist("items") if item.strip()]
    if items:
        return items
    items_text = request.POST.get("items_text", "")
    if not items_text.strip():
        return None
    return [line.strip() for line in items_text.splitlines() if line.strip()]


def _medication_tasks_from_post(
    request: Any, capture: InboxCapture
) -> list[dict[str, Any]]:
    payload = capture.normalized_payload or {}
    raw_drafts = payload.get("task_drafts")
    if not isinstance(raw_drafts, list):
        return []

    has_explicit_task_fields = "medication_task_count" in request.POST
    try:
        count = int(request.POST.get("medication_task_count", len(raw_drafts)))
    except (TypeError, ValueError):
        count = len(raw_drafts)

    reviewed_tasks: list[dict[str, Any]] = []
    for index, raw_draft in enumerate(raw_drafts[: max(0, count)]):
        if not isinstance(raw_draft, dict):
            continue
        prefix = f"medication_tasks-{index}"
        draft = dict(raw_draft)
        draft["selected"] = (
            request.POST.get(f"{prefix}-selected") == "on"
            if has_explicit_task_fields
            else draft.get("selected", True)
        )
        for field in (
            "title",
            "notes",
            "due_window_start_at",
            "due_at",
            "due_window_end_at",
        ):
            value = request.POST.get(f"{prefix}-{field}")
            if value is not None:
                draft[field] = value.strip()
        draft["reminders_enabled"] = (
            request.POST.get(f"{prefix}-reminders_enabled") == "on"
        )
        reviewed_tasks.append(draft)
    return reviewed_tasks


def _invalidate_organize_workspace_cache(user: User) -> None:
    bump_desktop_response_cache_version(
        namespace=ORGANIZE_WORKSPACE_CACHE_NAMESPACE,
        scope_token=user.id,
    )


@login_required
@require_POST
def convert_inbox_capture(request: Any, capture_id: Any) -> Any:
    capture = _get_accessible_capture(request.user, capture_id)
    normalized_payload = capture.normalized_payload or {}
    target_kind = normalize_capture_target_kind(request.POST.get("target_kind", "task"))
    proposal_index = _proposal_index_from_post(request)
    title = request.POST.get("title")
    notes = request.POST.get("notes")

    try:
        if normalized_payload.get("kind") == "medication_task_bundle":
            created_tasks = create_tasks_from_capture(
                capture,
                reviewed_tasks=_medication_tasks_from_post(request, capture),
            )
            messages.success(
                request,
                f"Created {len(created_tasks)} medication task"
                f"{'' if len(created_tasks) == 1 else 's'}.",
            )
        elif target_kind == "event":
            event_payload = build_capture_event_payload(
                capture,
                proposal_index=proposal_index,
                title=title,
                notes=notes,
                starts_at=request.POST.get("starts_at"),
                ends_at=request.POST.get("ends_at"),
                location=request.POST.get("location"),
            )
            event = convert_capture_to_event(capture, event_payload)
            messages.success(request, f"Created event: {event.title}")
        elif target_kind == "grocery_list":
            list_payload = build_capture_list_payload(
                capture,
                proposal_index=proposal_index,
                title=title,
                notes=notes,
                items=_items_from_post(request),
            )
            grocery_list = convert_capture_to_grocery_list(
                capture,
                name=list_payload["name"],
                description=list_payload["description"],
                owner=request.user,
                items=list_payload["items"],
            )
            messages.success(request, f"Created list: {grocery_list.name}")
        elif target_kind == "receipt":
            receipt_capture = convert_capture_to_receipt_capture(
                capture,
                owner=request.user,
                raw_text=notes or None,
            )
            messages.success(request, f"Created receipt review: {receipt_capture.id}")
        else:
            task_payload = build_capture_task_payload(
                capture,
                proposal_index=proposal_index,
                title=title,
                notes=notes,
            )
            task = convert_capture_to_task(
                capture,
                title=task_payload["title"],
                notes=task_payload["notes"],
            )
            messages.success(request, f"Created task: {task.title}")
    except (TaskCaptureCreateError, ValueError) as exc:
        messages.error(request, str(exc))
    else:
        _invalidate_organize_workspace_cache(request.user)

    return redirect("dashboard")


@login_required
@require_POST
def dismiss_inbox_capture(request: Any, capture_id: Any) -> Any:
    capture = _get_accessible_capture(request.user, capture_id)
    dismiss_capture(capture)
    _invalidate_organize_workspace_cache(request.user)
    messages.info(request, "Dismissed inbox item.")
    return redirect("dashboard")


@login_required
@feature_required("organize")
def tasks_board(request: Any) -> Any:
    """Web Tasks board: Overdue / Today / This Week / Unscheduled / Recently completed."""
    payload = get_dashboard_payload(request.user, request=request)

    family_ids = get_accessible_family_ids(request.user)
    recently_completed = list(
        recently_completed_tasks(
            FamilyTask.objects.filter(family_id__in=family_ids).select_related(
                "assigned_to",
                "family",
            )
        )
    )

    context = {
        "overdue_tasks": list(payload["overdue"]),
        "today_tasks": list(payload["today"]),
        "this_week_tasks": list(payload["this_week"]),
        "unscheduled_tasks": list(payload["unscheduled"]),
        "completed_tasks": recently_completed,
        "inbox_captures": list(payload["inbox"]),
    }
    return render(request, "organize/tasks_board.html", context)


@login_required
@feature_required("organize")
def task_create(request: Any) -> Any:
    """Create a new family task."""
    user = request.user
    user_families = get_accessible_family_ids(user)

    if not user_families:
        messages.error(request, "You must belong to a family to create a task.")
        return redirect("organize_tasks")

    if request.method == "POST":
        form = FamilyTaskWebForm(request.POST, user=user)
        if form.is_valid():
            try:
                with transaction.atomic():
                    task = form.save(commit=False)
                    task.created_by = user
                    task.save()
                    link_error = form.apply_event_link(task)
                    notify_task_lifecycle(task, created=True, actor=user)
                    _invalidate_organize_workspace_cache(user)
                    if link_error:
                        messages.warning(
                            request,
                            f'Task "{task.title}" created, but the event link '
                            f"failed: {link_error}",
                        )
                    else:
                        messages.success(
                            request, f'Task "{task.title}" created successfully!'
                        )
                    return redirect("organize_tasks")
            except Exception as e:
                logger.error(f"Failed to create task for user {user.id}: {e}")
                messages.error(request, "An error occurred while creating the task.")
    else:
        form = FamilyTaskWebForm(user=user)

    context = {
        "form": form,
        "is_edit": False,
    }
    return render(request, "organize/task_form.html", context)


@login_required
@feature_required("organize")
def task_edit(request: Any, task_id: Any) -> Any:
    """Edit an existing family task."""
    user = request.user
    family_ids = get_accessible_family_ids(user)

    task = get_object_or_404(
        FamilyTask.objects.filter(family_id__in=family_ids),
        id=task_id,
    )

    if request.method == "POST":
        old_status = task.status
        old_assignee_id = task.assigned_to_id
        form = FamilyTaskWebForm(request.POST, instance=task, user=user)
        if form.is_valid():
            try:
                with transaction.atomic():
                    updated = form.save()
                    notify_task_lifecycle(
                        updated,
                        created=False,
                        actor=user,
                        previous_assignee_id=old_assignee_id,
                        previous_status=old_status,
                    )
                    _invalidate_organize_workspace_cache(user)
                    messages.success(
                        request, f'Task "{task.title}" updated successfully!'
                    )
                    return redirect("organize_tasks")
            except Exception as e:
                logger.error(f"Failed to update task {task_id} for user {user.id}: {e}")
                messages.error(request, "An error occurred while updating the task.")
    else:
        form = FamilyTaskWebForm(instance=task, user=user)

    context = {
        "form": form,
        "task": task,
        "is_edit": True,
    }
    return render(request, "organize/task_form.html", context)


@login_required
@feature_required("organize")
@require_POST
def task_delete(request: Any, task_id: Any) -> Any:
    """Delete a family task."""
    user = request.user
    family_ids = get_accessible_family_ids(user)

    task = get_object_or_404(
        FamilyTask.objects.filter(family_id__in=family_ids),
        id=task_id,
    )

    try:
        title = task.title
        task.delete()
        _invalidate_organize_workspace_cache(user)
        messages.success(request, f'Task "{title}" deleted.')
        response = redirect("organize_tasks")
        response.status_code = 303
        return response
    except Exception as e:
        logger.error(f"Failed to delete task {task_id} for user {user.id}: {e}")
        messages.error(request, "An error occurred while deleting the task.")
        return redirect("organize_tasks")


@login_required
@feature_required("organize")
@require_POST
def toggle_task(request: Any, task_id: Any) -> Any:
    """Toggle a task's status between PENDING and COMPLETED."""
    user = request.user
    family_ids = get_accessible_family_ids(user)

    task = get_object_or_404(
        FamilyTask.objects.filter(family_id__in=family_ids),
        id=task_id,
    )

    try:
        with transaction.atomic():
            old_status = task.status
            if task.status == FamilyTask.Status.COMPLETED:
                task.status = FamilyTask.Status.PENDING
                action = "reopened"
            else:
                task.status = FamilyTask.Status.COMPLETED
                action = "completed"
            task.save()
            if (
                old_status != FamilyTask.Status.COMPLETED
                and task.status == FamilyTask.Status.COMPLETED
            ):
                if task.task_kind == FamilyTask.TaskKind.MEDICATION:
                    spawn_next_medication_occurrence(task)
                elif task.recurrence != FamilyTask.Recurrence.NONE:
                    spawn_next_occurrence(task)
            notify_task_lifecycle(
                task,
                created=False,
                actor=user,
                previous_assignee_id=task.assigned_to_id,
                previous_status=old_status,
            )
            _invalidate_organize_workspace_cache(user)
            messages.success(request, f'Task "{task.title}" marked as {action}.')
    except Exception as e:
        logger.error(f"Failed to toggle task {task_id} status for user {user.id}: {e}")
        messages.error(request, "An error occurred while updating the task status.")

    return redirect("organize_tasks")
