{% load static %}

{% block title %}{% if is_edit %}Edit{% else %}Create{% endif %} Task{% endblock %}

{% block extra_css %}
<style>
    .form-card {
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-6);
        max-width: 800px;
        margin: 0 auto;
    }

    .form-section {
        margin-bottom: var(--space-6);
        padding-bottom: var(--space-5);
        border-bottom: 1px solid var(--gray-200);
    }

    .form-section:last-child {
        margin-bottom: 0;
        padding-bottom: 0;
        border-bottom: none;
    }

    .form-section-title {
        font-size: var(--font-size-lg);
        font-weight: 600;
        color: var(--gray-900);
        margin-bottom: var(--space-4);
    }

    .form-actions {
        display: flex;
        justify-content: flex-end;
        gap: var(--space-3);
        padding-top: var(--space-4);
    }
</style>
{% endblock %}

{% block content %}
<div class="container py-4">
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="{% url 'organize_tasks' %}">Tasks</a></li>
            {% if is_edit %}
            <li class="breadcrumb-item active">Edit Task</li>
            {% else %}
            <li class="breadcrumb-item active">Create Task</li>
            {% endif %}
        </ol>
    </nav>

    <h1 class="mb-4">
        <i class="bi bi-check2-square me-2"></i>{% if is_edit %}Edit{% else %}Create{% endif %} Task
    </h1>

    <div class="form-card">
        <form method="post">
            {% csrf_token %}

            <div class="form-section">
                <h3 class="form-section-title">Task Details</h3>
                <div class="row g-3">
                    <div class="col-md-8">
                        <label for="{{ form.title.id_for_label }}" class="form-label">Title *</label>
                        {{ form.title }}
                        {% if form.title.errors %}
                        <div class="invalid-feedback d-block">{{ form.title.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-4">
                        <label for="{{ form.family.id_for_label }}" class="form-label">Family *</label>
                        {{ form.family }}
                        {% if form.family.errors %}
                        <div class="invalid-feedback d-block">{{ form.family.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.assigned_to.id_for_label }}" class="form-label">Assign To</label>
                        {{ form.assigned_to }}
                        {% if form.assigned_to.errors %}
                        <div class="invalid-feedback d-block">{{ form.assigned_to.errors.0 }}</div>
                        {% endif %}
                    </div>
                    {% if not task or task.task_kind != "MEDICATION" %}
                    <div class="col-md-6">
                        <label for="{{ form.due_at.id_for_label }}" class="form-label">Due At</label>
                        {{ form.due_at }}
                        {% if form.due_at.errors %}
                        <div class="invalid-feedback d-block">{{ form.due_at.errors.0 }}</div>
                        {% endif %}
                    </div>
                    {% endif %}
                    <div class="col-md-6">
                        <label for="{{ form.task_kind.id_for_label }}" class="form-label">Kind</label>
                        {{ form.task_kind }}
                        {% if form.task_kind.errors %}
                        <div class="invalid-feedback d-block">{{ form.task_kind.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.status.id_for_label }}" class="form-label">Status</label>
                        {{ form.status }}
                        {% if form.status.errors %}
                        <div class="invalid-feedback d-block">{{ form.status.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-12">
                        <label for="{{ form.notes.id_for_label }}" class="form-label">Notes</label>
                        {{ form.notes }}
                        {% if form.notes.errors %}
                        <div class="invalid-feedback d-block">{{ form.notes.errors.0 }}</div>
                        {% endif %}
                    </div>
                </div>
            </div>

            <div class="form-section" data-testid="linked-event-fields">
                <h3 class="form-section-title">Linked Event</h3>
                <p class="text-muted small mb-3">
                    Link this task to an event to set its due date from the event. The reminder
                    fires relative to that event time.
                </p>
                <div class="row g-3">
                    <div class="col-12">
                        <label for="{{ form.linked_event.id_for_label }}" class="form-label">Event</label>
                        {{ form.linked_event }}
                        <div class="form-text">{{ form.linked_event.help_text }}</div>
                        {% if form.linked_event.errors %}
                        <div class="invalid-feedback d-block">{{ form.linked_event.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.linked_event_anchor.id_for_label }}" class="form-label">Anchor</label>
                        {{ form.linked_event_anchor }}
                        <div class="form-text">{{ form.linked_event_anchor.help_text }}</div>
                        {% if form.linked_event_anchor.errors %}
                        <div class="invalid-feedback d-block">{{ form.linked_event_anchor.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.linked_event_offset_minutes.id_for_label }}" class="form-label">Reminder offset (minutes)</label>
                        {{ form.linked_event_offset_minutes }}
                        <div class="form-text">{{ form.linked_event_offset_minutes.help_text }}</div>
                        {% if form.linked_event_offset_minutes.errors %}
                        <div class="invalid-feedback d-block">{{ form.linked_event_offset_minutes.errors.0 }}</div>
                        {% endif %}
                    </div>
                </div>
            </div>

            {% if task.task_kind == "MEDICATION" %}
            <div class="form-section" data-testid="medication-task-fields">
                <h3 class="form-section-title">Medication Schedule</h3>
                <div class="row g-3">
                    <div class="col-md-6">
                        <label for="{{ form.medication_name.id_for_label }}" class="form-label">Medicine</label>
                        {{ form.medication_name }}
                        {% if form.medication_name.errors %}
                        <div class="invalid-feedback d-block">{{ form.medication_name.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.dosage_text.id_for_label }}" class="form-label">Dosage</label>
                        {{ form.dosage_text }}
                        {% if form.dosage_text.errors %}
                        <div class="invalid-feedback d-block">{{ form.dosage_text.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-4">
                        <label for="{{ form.due_window_start_at.id_for_label }}" class="form-label">Window Start</label>
                        {{ form.due_window_start_at }}
                        {% if form.due_window_start_at.errors %}
                        <div class="invalid-feedback d-block">{{ form.due_window_start_at.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-4">
                        <label for="{{ form.due_at.id_for_label }}" class="form-label">Preferred Time</label>
                        {{ form.due_at }}
                        {% if form.due_at.errors %}
                        <div class="invalid-feedback d-block">{{ form.due_at.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-4">
                        <label for="{{ form.due_window_end_at.id_for_label }}" class="form-label">Window End</label>
                        {{ form.due_window_end_at }}
                        {% if form.due_window_end_at.errors %}
                        <div class="invalid-feedback d-block">{{ form.due_window_end_at.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.min_interval_hours.id_for_label }}" class="form-label">Minimum Interval Hours</label>
                        {{ form.min_interval_hours }}
                        {% if form.min_interval_hours.errors %}
                        <div class="invalid-feedback d-block">{{ form.min_interval_hours.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-6">
                        <label for="{{ form.max_interval_hours.id_for_label }}" class="form-label">Maximum Interval Hours</label>
                        {{ form.max_interval_hours }}
                        {% if form.max_interval_hours.errors %}
                        <div class="invalid-feedback d-block">{{ form.max_interval_hours.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-12">
                        <label for="{{ form.instructions.id_for_label }}" class="form-label">Instructions</label>
                        {{ form.instructions }}
                        {% if form.instructions.errors %}
                        <div class="invalid-feedback d-block">{{ form.instructions.errors.0 }}</div>
                        {% endif %}
                    </div>
                    <div class="col-md-4">
                        <div class="form-check">
                            {{ form.is_as_needed }}
                            <label for="{{ form.is_as_needed.id_for_label }}" class="form-check-label">As needed</label>
                        </div>
                    </div>
                    <div class="col-md-4">
                        <div class="form-check">
                            {{ form.series_is_active }}
                            <label for="{{ form.series_is_active.id_for_label }}" class="form-check-label">Active schedule</label>
                        </div>
                    </div>
                    <div class="col-md-4">
                        <div class="form-check">
                            {{ form.reminders_enabled }}
                            <label for="{{ form.reminders_enabled.id_for_label }}" class="form-check-label">Reminder enabled</label>
                        </div>
                    </div>
                </div>
            </div>
            {% endif %}

            <div class="form-actions">
                <a href="{% url 'organize_tasks' %}" class="btn btn-outline-secondary">
                    Cancel
                </a>
                <button type="submit" class="btn btn-primary" id="save-task-btn">
                    <i class="bi bi-check-lg me-1"></i>{% if is_edit %}Save Changes{% else %}Create Task{% endif %}
                </button>
            </div>
        </form>
    </div>
</div>
{% endblock %}

{% block extra_js %}
<script>
    // When an event is linked, its due date is derived from the event, so the
    // manual "Due At" input is read-only to avoid a confusing conflict.
    (function () {
        var eventSelect = document.getElementById("{{ form.linked_event.id_for_label }}");
        var dueAtInput = document.getElementById("{{ form.due_at.id_for_label }}");
        if (!eventSelect || !dueAtInput) {
            return;
        }
        function syncDueAtState() {
            var linked = !!eventSelect.value;
            dueAtInput.readOnly = linked;
            dueAtInput.classList.toggle("bg-light", linked);
        }
        eventSelect.addEventListener("change", syncDueAtState);
        syncDueAtState();
    })();
</script>
{% endblock %}
