151	  if (completed && task.completed_at) {
152	    return `Completed ${formatDateTime(task.completed_at)}`;
153	  }
154	  if (task.due_at) {
155	    return `Due ${formatDateTime(task.due_at)}`;
156	  }
157	  if (task.due_window_end_at) {
158	    return `By ${formatDateTime(task.due_window_end_at)}`;
159	  }
160	  return null;
