async listEvents(filters?: DesktopEventFilters): Promise<DesktopEvent[]> {
  const buildPath = (page: number): string => {
    const params = new URLSearchParams();
    if (filters?.start_date) params.set("start_date", filters.start_date);
    if (filters?.end_date) params.set("end_date", filters.end_date);
    if (filters?.family_id) params.set("family_id", filters.family_id);
    if (filters?.search) params.set("search", filters.search);
    params.set("page_size", "100");
    params.set("fields", "compact");
    if (page > 1) params.set("page", String(page));
    return `events/?${params.toString()}`;
  };

  // Page 1, then follow up to MAX_PAGES — matches mobile behaviour.
  const MAX_PAGES = 10;
  const first = await request<unknown>(buildPath(1));
  const firstResults = normalizeArray<DesktopEvent>(first);
  const count = (first as { count?: number } | null)?.count;
  const next = (first as { next?: unknown } | null)?.next;
  if (!next || !count) return firstResults;

  const totalPages = Math.min(Math.ceil(count / 100), MAX_PAGES);
  if (totalPages <= 1) return firstResults;
  const pageNums = Array.from({ length: totalPages - 1 }, (_, i) => i + 2);
  const rest = await Promise.all(
    pageNums.map(async (page) =>
      normalizeArray<DesktopEvent>(await request<unknown>(buildPath(page))),
    ),
  );
  return [...firstResults, ...rest.flat()];
},

