/**
 * Pure formatters shared by the events surface.
 * No React imports — kept easy to unit-test.
 */

import type { DesktopEvent } from '../../lib/api';

const DAY_MS = 24 * 60 * 60 * 1000;

export function formatEventMeta(start: string, end: string, isAllDay = false): string {
  const s = new Date(start);
  const e = new Date(end);
  if (Number.isNaN(s.getTime())) return '';
  const date = s.toLocaleDateString(undefined, {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
  });
  // All-day events store a midnight time; show the date plus an "All day"
  // label instead of "12:00 AM" (mirrors mobile getTimeRangeString).
  if (isAllDay) return `${date} · All day`;
  const timeFmt: Intl.DateTimeFormatOptions = { hour: 'numeric', minute: '2-digit' };
  const startStr = s.toLocaleTimeString(undefined, timeFmt);
  if (Number.isNaN(e.getTime())) return `${date} · ${startStr}`;
  const endStr = e.toLocaleTimeString(undefined, timeFmt);
  return `${date} · ${startStr} – ${endStr}`;
}

export function formatEventTimeRange(start: string, end: string, isAllDay = false): string {
  const s = new Date(start);
  const e = new Date(end);
  if (Number.isNaN(s.getTime())) return '';
  // Mirror mobile getTimeRangeString: single-day all-day events read "All day";
  // multi-day all-day events read as a date span.
  if (isAllDay) {
    const dateFmt: Intl.DateTimeFormatOptions = { month: 'short', day: 'numeric' };
    if (Number.isNaN(e.getTime()) || sameCalendarDay(s, e)) return 'All day';
    return `${s.toLocaleDateString(undefined, dateFmt)} – ${e.toLocaleDateString(undefined, dateFmt)}`;
  }
  const timeFmt: Intl.DateTimeFormatOptions = { hour: 'numeric', minute: '2-digit' };
  const startStr = s.toLocaleTimeString(undefined, timeFmt);
  if (Number.isNaN(e.getTime())) return startStr;
  const endStr = e.toLocaleTimeString(undefined, timeFmt);
  return `${startStr} – ${endStr}`;
}

function sameCalendarDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export function groupEventsByDay(
  events: DesktopEvent[]
): { dayKey: string; label: string; events: DesktopEvent[] }[] {
  const buckets = new Map<string, DesktopEvent[]>();
  for (const ev of events) {
    const d = new Date(ev.start_time);
    if (Number.isNaN(d.getTime())) continue;
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
      d.getDate()
    ).padStart(2, '0')}`;
    const list = buckets.get(key) ?? [];
    list.push(ev);
    buckets.set(key, list);
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return Array.from(buckets.entries())
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([dayKey, list]) => {
      const d = new Date(`${dayKey}T00:00:00`);
      const delta = Math.round((d.getTime() - today.getTime()) / DAY_MS);
      const label =
        delta === 0
          ? 'Today'
          : delta === 1
            ? 'Tomorrow'
            : d.toLocaleDateString(undefined, {
                weekday: 'long',
                month: 'short',
                day: 'numeric',
              });
      list.sort((a, b) => (a.start_time < b.start_time ? -1 : 1));
      return { dayKey, label, events: list };
    });
}

export function toLocalInputValue(iso: string | undefined | null): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const pad = (n: number) => String(n).padStart(2, '0');
  return (
    `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}` +
    `T${pad(d.getHours())}:${pad(d.getMinutes())}`
  );
}

export function fromLocalInputValue(value: string): string {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  return d.toISOString();
}

