  apiBaseUrl?: string;
  mobileApiBaseUrl?: string;
}) {
  return {
    getDeviceId: vi.fn().mockResolvedValue("desktop-device-1"),
    getSession: vi.fn().mockResolvedValue(null),
    saveSession: vi.fn(),
    clearSession: vi.fn(),
    getPreferences: vi.fn().mockResolvedValue({
      apiBaseUrl: overrides?.apiBaseUrl ?? "http://localhost:8100/api",
      mobileApiBaseUrl:
