      panelShortcut: "CommandOrControl+Shift+Space",
      openOnLogin: false,
      closeToTray: true,
    }),
  };
}

describe("createDesktopApiClient", () => {
  it("sanitizes HTML server errors before surfacing them to the desktop user", async () => {
    const deps = createDeps();
    const api = createDesktopApiClient(deps);

    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue(
        new Response(
