}

interface DesktopApiDeps {
  getDeviceId(): Promise<string>;
  getSession(): Promise<DesktopStoredSession | null>;
  saveSession(session: DesktopStoredSession): Promise<DesktopStoredSession>;
  clearSession(): Promise<void>;
  getPreferences(): Promise<DesktopPreferences>;
  request?(request: DesktopNetworkRequest): Promise<DesktopNetworkResponse>;
}

export interface DesktopApiRequestOptions {
  base?: "api" | "mobile";
  retryOnAuth?: boolean;
}

function joinUrl(baseUrl: string, pathname: string): string {
  const safeBaseUrl = normalizeDesktopBaseUrl(baseUrl);
  const normalizedBase = safeBaseUrl.endsWith("/")
    ? safeBaseUrl
    : `${safeBaseUrl}/`;
  const normalizedPath = pathname.replace(/^\/+/, "");
  return new URL(normalizedPath, normalizedBase).toString();
}

function asString(value: unknown, fallback = ""): string {
  if (typeof value === "string") {
    return value;
  }
  if (typeof value === "number") {
    return String(value);
  }
  return fallback;
}

function normalizeArray<T>(payload: unknown): T[] {
  if (Array.isArray(payload)) {
    return payload as T[];
  }
  if (
    typeof payload === "object" &&
    payload !== null &&
    Array.isArray((payload as { results?: unknown[] }).results)
  ) {
    return (payload as { results: T[] }).results;
  }
  return [];
}

function normalizeTripDateStatus(value: unknown): DesktopTripDateStatus {
  const normalized = asString(value).toUpperCase();
  if (normalized === "UNKNOWN") return "UNKNOWN";
  if (normalized === "TENTATIVE") return "TENTATIVE";
  return "EXACT";
}

function serializeTripDateStatus(
  value: DesktopTripDateStatus | undefined,
): "exact" | "unknown" | undefined {
  if (!value) return undefined;
  return value === "UNKNOWN" ? "unknown" : "exact";
}

function normalizeTrip(payload: unknown): DesktopTrip {
  const trip = payload as DesktopTrip & { date_status?: unknown };
  return {
    ...trip,
    date_status: normalizeTripDateStatus(trip.date_status),
  };
}

function normalizeTripWorkspace(payload: unknown): DesktopTripWorkspace {
  const workspace = payload as DesktopTripWorkspace & { date_status?: unknown };
  return {
    ...workspace,
    date_status: normalizeTripDateStatus(workspace.date_status),
    activity_count:
      typeof workspace.activity_count === "number"
        ? workspace.activity_count
        : (workspace.recent_activity?.length ?? 0),
  };
}

interface ResponseLike {
  ok: boolean;
  status: number;
  text(): Promise<string>;
}

async function parseResponseBody(response: ResponseLike): Promise<unknown> {
  const text = await response.text();
  if (!text) {
    return null;
  }
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return text;
  }
}

function extractErrorMessage(payload: unknown, status: number): string {
  if (typeof payload === "string" && payload.trim()) {
    const trimmedPayload = payload.trim();
    if (
      /^<!doctype html\b/i.test(trimmedPayload) ||
      /^<html\b/i.test(trimmedPayload)
    ) {
      return `Request failed with status ${status}`;
    }
    return payload;
  }
  if (payload && typeof payload === "object") {
    const detail = (payload as { detail?: unknown }).detail;
    if (typeof detail === "string" && detail.trim()) {
      return detail;
    }
    const error = (payload as { error?: unknown }).error;
    if (typeof error === "string" && error.trim()) {
      return error;
    }
  }
  return `Request failed with status ${status}`;
}

function headersToObject(headers?: HeadersInit): Record<string, string> {
  return Object.fromEntries(new Headers(headers ?? {}).entries());
}

async function binaryPartToArrayBuffer(part: Blob): Promise<ArrayBuffer> {
  if (typeof part.arrayBuffer === "function") {
    return part.arrayBuffer();
  }
  return new Response(part).arrayBuffer();
}

async function serializeRequestBody(
  body?: BodyInit | null,
): Promise<DesktopNetworkRequestBody | null | undefined> {
  if (body === undefined) {
    return undefined;
  }
  if (body === null) {
    return null;
  }
  if (typeof body === "string") {
    return {
      kind: "text",
      value: body,
    };
  }
  if (body instanceof URLSearchParams) {
    return {
      kind: "text",
      value: body.toString(),
    };
  }
  if (body instanceof FormData) {
    const fields = await Promise.all(
      Array.from(body.entries()).map(async ([name, value]) => {
        if (typeof value === "string") {
          return {
            name,
            value: {
              kind: "text" as const,
              value,
            },
          };
        }

        return {
          name,
          value: {
            kind: "binary" as const,
            filename: value.name || "upload.bin",
            mimeType: value.type || "application/octet-stream",
            bytes: await binaryPartToArrayBuffer(value),
          },
        };
      }),
    );

    return {
      kind: "form-data",
      fields,
    };
  }

  throw new Error("Unsupported desktop network request body.");
}

function fromDesktopNetworkResponse(
  response: DesktopNetworkResponse,
): ResponseLike {
  return {
    ok: response.ok,
    status: response.status,
    async text() {
      return response.bodyText;
    },
  };
}

function getPrimaryFamilyId(
  session: DesktopStoredSession | null,
): string | null {
  const user = session?.user;
  const profilePrimaryFamily =
    user?.profile && typeof user.profile === "object"
      ? (user.profile.primary_family ?? null)
      : null;
  return (
    asString(profilePrimaryFamily ?? user?.primary_family ?? null, "") || null
  );
}

let refreshPromise: Promise<DesktopStoredSession | null> | null = null;

export type DesktopApiClient = ReturnType<typeof createDesktopApiClient>;

export function createDesktopApiClient(deps: DesktopApiDeps) {
  async function sendRequest(
    url: string,
    init?: RequestInit,
  ): Promise<ResponseLike> {
    if (!deps.request) {
      return fetch(url, init);
    }

    const response = await deps.request({
      url,
      method: init?.method,
      headers: headersToObject(init?.headers),
      body: await serializeRequestBody(init?.body),
    });

    return fromDesktopNetworkResponse(response);
  }

  async function refreshSession(
    currentSession: DesktopStoredSession,
  ): Promise<DesktopStoredSession | null> {
    if (refreshPromise) {
      return refreshPromise;
    }

    refreshPromise = (async () => {
      const preferences = await deps.getPreferences();
      const response = await sendRequest(
        joinUrl(preferences.mobileApiBaseUrl, "token/refresh/"),
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Client-App": "desktop",
            "X-Client-Platform": "desktop",
            "X-Device-ID": currentSession.deviceId,
          },
          body: JSON.stringify({
            refresh: currentSession.refreshToken,
            device_id: currentSession.deviceId,
          }),
        },
      );
      const payload = await parseResponseBody(response);
      if (!response.ok || !payload || typeof payload !== "object") {
        await deps.clearSession();
        return null;
      }

      const nextSession: DesktopStoredSession = {
        ...currentSession,
        accessToken: asString((payload as { access?: unknown }).access),
        refreshToken:
          asString((payload as { refresh?: unknown }).refresh) ||
          currentSession.refreshToken,
        savedAt: new Date().toISOString(),
      };
      await deps.saveSession(nextSession);
      return nextSession;
    })().finally(() => {
      refreshPromise = null;
    });

    return refreshPromise;
  }

  async function request<T>(
    pathname: string,
    init?: RequestInit,
    options?: DesktopApiRequestOptions,
  ): Promise<T> {
    const preferences = await deps.getPreferences();
    const session = await deps.getSession();
    const baseUrl =
      options?.base === "mobile"
        ? preferences.mobileApiBaseUrl
        : preferences.apiBaseUrl;

    const headers = new Headers(init?.headers ?? {});
    headers.set("X-Client-App", "desktop");
    headers.set("X-Client-Platform", "desktop");
    if (!(init?.body instanceof FormData)) {
      headers.set("Content-Type", "application/json");
    }
    if (session?.accessToken) {
      headers.set("Authorization", `Bearer ${session.accessToken}`);
    }
    if (session?.deviceId) {
      headers.set("X-Device-ID", session.deviceId);
    }

    const response = await sendRequest(joinUrl(baseUrl, pathname), {
      ...init,
      headers,
    });

    if (
      response.status === 401 &&
      options?.retryOnAuth !== false &&
      session?.refreshToken
    ) {
      const refreshedSession = await refreshSession(session);
      if (refreshedSession?.accessToken) {
        return request<T>(pathname, init, {
          ...options,
          retryOnAuth: false,
        });
      }
    }

    const payload = await parseResponseBody(response);

    if (!response.ok) {
      throw new DesktopApiError(
        extractErrorMessage(payload, response.status),
        response.status,
        payload,
      );
    }

    return payload as T;
  }

  function postJson<T>(pathname: string, body: unknown = {}): Promise<T> {
    return request<T>(pathname, {
      method: "POST",
      body: JSON.stringify(body),
    });
  }

  function patchJson<T>(pathname: string, body: unknown): Promise<T> {
    return request<T>(pathname, {
      method: "PATCH",
      body: JSON.stringify(body),
    });
  }

  return {
    async apiRequest<T>(
      pathname: string,
      init?: RequestInit,
      options?: DesktopApiRequestOptions,
    ): Promise<T> {
      return request<T>(pathname, init, options);
    },

    async login(credentials: { email: string; password: string }) {
      const existingSession = await deps.getSession();
      const deviceId = existingSession?.deviceId ?? (await deps.getDeviceId());
      const payload = await request<{
        access: string;
        refresh: string;
        user: DesktopStoredSession["user"];
      }>(
        "auth/login/",
        {
          method: "POST",
          body: JSON.stringify({
            email: credentials.email,
            password: credentials.password,
            device_id: deviceId,
            device_name: "ClanCal",
            device_type: "desktop",
            extended_session: true,
          }),
        },
        {
          base: "mobile",
          retryOnAuth: false,
        },
      );

      const session: DesktopStoredSession = {
        accessToken: payload.access,
        refreshToken: payload.refresh,
        user: payload.user,
        deviceId,
        savedAt: new Date().toISOString(),
      };
      await deps.saveSession(session);
      return session;
    },

    async redeemGoogleDesktopGrant(callback: DesktopAuthCallback) {
      const deviceId = await deps.getDeviceId();
      const payload = await request<{
        access: string;
        refresh: string;
        user: DesktopStoredSession["user"];
      }>(
        "auth/google/desktop/redeem/",
        {
          method: "POST",
          body: JSON.stringify({
            grant: callback.grant,
            state: callback.state,
            device_id: deviceId,
            device_name: "ClanCal",
            device_type: "desktop",
            client_app: "desktop",
          }),
        },
        {
          base: "mobile",
          retryOnAuth: false,
        },
      );

      const session: DesktopStoredSession = {
        accessToken: payload.access,
        refreshToken: payload.refresh,
        user: payload.user,
        deviceId,
        savedAt: new Date().toISOString(),
      };
      await deps.saveSession(session);
      return session;
    },

    async listThreads() {
      return request<DesktopThread[]>("family-agent/threads/");
    },

    async createThread(payload?: { title?: string }) {
      return request<DesktopThread>("family-agent/threads/", {
        method: "POST",
        body: JSON.stringify(payload ?? {}),
      });
    },

    async updateThread(threadId: string, payload: { title: string }) {
      return request<DesktopThread>(`family-agent/threads/${threadId}/`, {
