    async listCaptures() {
      const payload = await request<unknown>("organize/inbox-captures/");
      return normalizeArray<DesktopCapture>(payload);
    },

    async createDesktopCapture(input: DesktopCaptureInput) {
      const hasPhoto = Boolean(input.photo);
      if (hasPhoto) {
        const formData = new FormData();
        Object.entries(input).forEach(([key, value]) => {
          if (value === undefined || value === null || value === "") {
            return;
          }
          if (key === "photo" && value instanceof File) {
            formData.append(key, value);
            return;
          }
          if (key === "raw_payload" && typeof value === "object") {
            formData.append(key, JSON.stringify(value));
            return;
          }
          formData.append(key, String(value));
        });
        return request<DesktopCapture>("organize/inbox-captures/desktop/", {
          method: "POST",
          body: formData,
        });
      }

      return request<DesktopCapture>("organize/inbox-captures/desktop/", {
        method: "POST",
        body: JSON.stringify(input),
      });
    },

    async getDashboard() {
