    // ── All reminders for the user (cross-event) ────────────────────────
    async listAllReminders(): Promise<DesktopReminderListItem[]> {
      const params = new URLSearchParams({
        page_size: "100",
        fields: "compact",
      });
      const payload = await request<unknown>(`events/?${params}`);
      const nowMs = Date.now();
      return normalizeArray<DesktopEvent>(payload)
        .flatMap((event) => {
          const reminder = event.user_reminder;
          if (!reminder?.reminder_time) {
            return [];
          }
          const reminderTimeMs = Date.parse(reminder.reminder_time);
          if (!Number.isFinite(reminderTimeMs) || reminderTimeMs < nowMs) {
            return [];
          }
          return [
            {
              event,
              reminder_time: reminder.reminder_time,
              is_sent: Boolean(reminder.last_sent_at),
            },
          ];
        })
        .sort((a, b) => a.reminder_time.localeCompare(b.reminder_time));
    },
