    };
  }
  if (body instanceof FormData) {
    const fields = await Promise.all(
      Array.from(body.entries()).map(async ([name, value]) => {
        if (typeof value === "string") {
          return {
            name,
            value: {
              kind: "text" as const,
              value,
            },
          };
        }

        return {
          name,
          value: {
            kind: "binary" as const,
            filename: value.name || "upload.bin",
            mimeType: value.type || "application/octet-stream",
            bytes: await binaryPartToArrayBuffer(value),
          },
        };
      }),
    );

    return {
      kind: "form-data",
      fields,
    };
  }

  throw new Error("Unsupported desktop network request body.");
}

function fromDesktopNetworkResponse(
  response: DesktopNetworkResponse,
): ResponseLike {
  return {
    ok: response.ok,
    status: response.status,
    async text() {
      return response.bodyText;
    },
  };
}

function getPrimaryFamilyId(
  session: DesktopStoredSession | null,
): string | null {
  const user = session?.user;
  const profilePrimaryFamily =
    user?.profile && typeof user.profile === "object"
      ? (user.profile.primary_family ?? null)
      : null;
  return (
    asString(profilePrimaryFamily ?? user?.primary_family ?? null, "") || null
  );
}

let refreshPromise: Promise<DesktopStoredSession | null> | null = null;

export type DesktopApiClient = ReturnType<typeof createDesktopApiClient>;

export function createDesktopApiClient(deps: DesktopApiDeps) {
  async function sendRequest(
    url: string,
    init?: RequestInit,
  ): Promise<ResponseLike> {
    if (!deps.request) {
      return fetch(url, init);
    }

    const response = await deps.request({
      url,
      method: init?.method,
      headers: headersToObject(init?.headers),
      body: await serializeRequestBody(init?.body),
    });

    return fromDesktopNetworkResponse(response);
  }

  async function refreshSession(
    currentSession: DesktopStoredSession,
  ): Promise<DesktopStoredSession | null> {
    if (refreshPromise) {
      return refreshPromise;
    }

    refreshPromise = (async () => {
      const preferences = await deps.getPreferences();
      const response = await sendRequest(
        joinUrl(preferences.mobileApiBaseUrl, "token/refresh/"),
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Client-App": "desktop",
            "X-Client-Platform": "desktop",
            "X-Device-ID": currentSession.deviceId,
          },
          body: JSON.stringify({
            refresh: currentSession.refreshToken,
            device_id: currentSession.deviceId,
          }),
        },
      );
      const payload = await parseResponseBody(response);
      if (!response.ok || !payload || typeof payload !== "object") {
        await deps.clearSession();
        return null;
      }

      const nextSession: DesktopStoredSession = {
        ...currentSession,
        accessToken: asString((payload as { access?: unknown }).access),
        refreshToken:
          asString((payload as { refresh?: unknown }).refresh) ||
          currentSession.refreshToken,
        savedAt: new Date().toISOString(),
      };
      await deps.saveSession(nextSession);
      return nextSession;
    })().finally(() => {
      refreshPromise = null;
    });

    return refreshPromise;
  }

  async function request<T>(
    pathname: string,
    init?: RequestInit,
    options?: DesktopApiRequestOptions,
  ): Promise<T> {
    const preferences = await deps.getPreferences();
    const session = await deps.getSession();
    const baseUrl =
      options?.base === "mobile"
        ? preferences.mobileApiBaseUrl
        : preferences.apiBaseUrl;

    const headers = new Headers(init?.headers ?? {});
    headers.set("X-Client-App", "desktop");
    headers.set("X-Client-Platform", "desktop");
    if (!(init?.body instanceof FormData)) {
      headers.set("Content-Type", "application/json");
    }
    if (session?.accessToken) {
      headers.set("Authorization", `Bearer ${session.accessToken}`);
    }
    if (session?.deviceId) {
      headers.set("X-Device-ID", session.deviceId);
    }

    const response = await sendRequest(joinUrl(baseUrl, pathname), {
      ...init,
      headers,
    });

    if (
      response.status === 401 &&
      options?.retryOnAuth !== false &&
      session?.refreshToken
    ) {
      const refreshedSession = await refreshSession(session);
      if (refreshedSession?.accessToken) {
        return request<T>(pathname, init, {
          ...options,
          retryOnAuth: false,
        });
      }
    }

    const payload = await parseResponseBody(response);

    if (!response.ok) {
      throw new DesktopApiError(
        extractErrorMessage(payload, response.status),
        response.status,
        payload,
      );
    }

    return payload as T;
  }

  function postJson<T>(pathname: string, body: unknown = {}): Promise<T> {
    return request<T>(pathname, {
      method: "POST",
      body: JSON.stringify(body),
    });
  }

  function patchJson<T>(pathname: string, body: unknown): Promise<T> {
    return request<T>(pathname, {
      method: "PATCH",
      body: JSON.stringify(body),
    });
  }

  return {
    async apiRequest<T>(
      pathname: string,
      init?: RequestInit,
      options?: DesktopApiRequestOptions,
    ): Promise<T> {
      return request<T>(pathname, init, options);
    },

    async login(credentials: { email: string; password: string }) {
      const existingSession = await deps.getSession();
      const deviceId = existingSession?.deviceId ?? (await deps.getDeviceId());
      const payload = await request<{
        access: string;
        refresh: string;
        user: DesktopStoredSession["user"];
      }>(
        "auth/login/",
        {
          method: "POST",
          body: JSON.stringify({
            email: credentials.email,
            password: credentials.password,
            device_id: deviceId,
            device_name: "ClanCal",
            device_type: "desktop",
            extended_session: true,
          }),
        },
        {
          base: "mobile",
          retryOnAuth: false,
        },
      );

      const session: DesktopStoredSession = {
        accessToken: payload.access,
        refreshToken: payload.refresh,
        user: payload.user,
        deviceId,
        savedAt: new Date().toISOString(),
      };
      await deps.saveSession(session);
      return session;
    },

    async redeemGoogleDesktopGrant(callback: DesktopAuthCallback) {
      const deviceId = await deps.getDeviceId();
      const payload = await request<{
        access: string;
        refresh: string;
        user: DesktopStoredSession["user"];
      }>(
        "auth/google/desktop/redeem/",
        {
          method: "POST",
          body: JSON.stringify({
            grant: callback.grant,
            state: callback.state,
            device_id: deviceId,
            device_name: "ClanCal",
            device_type: "desktop",
            client_app: "desktop",
          }),
        },
        {
          base: "mobile",
          retryOnAuth: false,
        },
      );

      const session: DesktopStoredSession = {
        accessToken: payload.access,
        refreshToken: payload.refresh,
        user: payload.user,
        deviceId,
        savedAt: new Date().toISOString(),
      };
      await deps.saveSession(session);
      return session;
    },

