    async getWidgetLayout(surface: string): Promise<DesktopWidgetLayout> {
      const params = new URLSearchParams({ surface });
      const payload = await request<DesktopWidgetLayout>(
        `desktop/widget-layout/?${params.toString()}`,
      );
      const rawTiles: unknown = Array.isArray(payload?.tiles)
        ? payload.tiles
        : [];
      const tiles: DesktopWidgetTile[] = (rawTiles as unknown[]).flatMap(
        (raw): DesktopWidgetTile[] => {
          if (!raw || typeof raw !== "object") return [];
          const t = raw as Partial<DesktopWidgetTile>;
          if (
            typeof t.id !== "string" ||
            typeof t.x !== "number" ||
            typeof t.y !== "number" ||
            typeof t.w !== "number" ||
            typeof t.h !== "number"
          ) {
            return [];
          }
          return [{ id: t.id, x: t.x, y: t.y, w: t.w, h: t.h }];
        },
      );
      return {
        surface:
          typeof payload?.surface === "string" ? payload.surface : surface,
        tiles,
      };
    },

