import { useCallback, useEffect, useState } from 'react';

import { useRequiredDesktopApi } from '../../lib/DesktopApiContext';
import type {
  DesktopApiClient,
  DesktopDashboard,
  DesktopEvent,
  DesktopTask,
} from '../../lib/api';
import { TasksScreen } from '../TasksScreen';

const DAY_MS = 24 * 60 * 60 * 1000;

function toDateParam(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

interface TaskBuckets {
  overdue: DesktopTask[];
  today: DesktopTask[];
  thisWeek: DesktopTask[];
  unscheduled: DesktopTask[];
  completed: DesktopTask[];
}

const EMPTY_BUCKETS: TaskBuckets = {
  overdue: [],
  today: [],
  thisWeek: [],
  unscheduled: [],
  completed: [],
};

function errorMessage(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message : fallback;
}

function bucketsFromDashboard(
  dashboard: DesktopDashboard,
  completed: DesktopTask[]
): TaskBuckets {
  return {
    overdue: dashboard.overdue ?? [],
    today: dashboard.today ?? [],
    thisWeek: dashboard.this_week ?? [],
    unscheduled: dashboard.unscheduled ?? [],
    completed,
  };
}

async function loadTaskBuckets(api: DesktopApiClient): Promise<TaskBuckets> {
  const [dashboard, completed] = await Promise.all([
    api.getDashboard(),
    api.listTasks({ status: 'COMPLETED' }),
  ]);
  return bucketsFromDashboard(dashboard, completed);
}

export function TasksSurface({ createSignal = 0 }: { createSignal?: number }) {
  const api = useRequiredDesktopApi();
  const [buckets, setBuckets] = useState<TaskBuckets>(EMPTY_BUCKETS);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);

  const refreshTasks = useCallback(async () => {
    const next = await loadTaskBuckets(api);
    setBuckets(next);
    setError(null);
    return next;
  }, [api]);

  useEffect(() => {
    let cancelled = false;

    void (async () => {
      setLoading(true);
      try {
        const next = await loadTaskBuckets(api);
        if (!cancelled) {
          setBuckets(next);
          setError(null);
        }
      } catch (loadError) {
        if (!cancelled) {
          setError(errorMessage(loadError, 'Unable to load tasks.'));
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [api]);

  const handleCreateTask = useCallback(
    async (input: { title: string; notes?: string; due_at?: string | null }) => {
      setError(null);
      setStatus(null);
      try {
        await api.createTask(input);
        await refreshTasks();
        setStatus('Task created.');
        return true;
      } catch (createError) {
        setError(errorMessage(createError, 'Unable to create the task.'));
        return false;
      }
    },
    [api, refreshTasks]
  );

  const handleUpdateTask = useCallback(
    async (
      taskId: string,
      input: {
        title?: string;
        notes?: string;
        due_at?: string | null;
        status?: string;
      }
    ) => {
      setError(null);
      setStatus(null);
      try {
        await api.updateTask(taskId, input);
        await refreshTasks();
        setStatus('Task updated.');
        return true;
      } catch (updateError) {
        setError(errorMessage(updateError, 'Unable to update the task.'));
        return false;
      }
    },
    [api, refreshTasks]
  );

  const loadLinkableEvents = useCallback(async (): Promise<DesktopEvent[]> => {
    // Bounded window so recurring events don't surface occurrences years out;
    // soonest-first. Mirrors the web task form's event picker scope.
    const now = new Date();
    const start = new Date(now.getTime() - DAY_MS);
    const end = new Date(now.getTime() + 365 * DAY_MS);
    const events = await api.listEvents({
      start_date: toDateParam(start),
      end_date: toDateParam(end),
    });
    return [...events].sort((a, b) =>
      a.start_time < b.start_time ? -1 : a.start_time > b.start_time ? 1 : 0
    );
  }, [api]);

  const handleLinkTaskToEvent = useCallback(
    async (
      taskId: string,
      input: { event_id: string; anchor?: 'START' | 'END'; offset_minutes?: number | null }
    ) => {
      setError(null);
      setStatus(null);
      try {
        await api.linkTaskToEvent(taskId, input);
        await refreshTasks();
        setStatus('Task linked to event.');
        return true;
      } catch (linkError) {
        setError(errorMessage(linkError, 'Unable to link the task to an event.'));
        return false;
      }
    },
    [api, refreshTasks]
  );

  const handleUnlinkTaskFromEvent = useCallback(
    async (taskId: string) => {
      setError(null);
      setStatus(null);
      try {
        await api.unlinkTaskFromEvent(taskId);
        await refreshTasks();
        setStatus('Task unlinked from event.');
        return true;
      } catch (unlinkError) {
        setError(errorMessage(unlinkError, 'Unable to unlink the task from the event.'));
        return false;
      }
    },
    [api, refreshTasks]
  );

  const handleDeleteTask = useCallback(
    async (taskId: string) => {
      setError(null);
      setStatus(null);
      try {
        await api.deleteTask(taskId);
        await refreshTasks();
        setStatus('Task deleted.');
        return true;
      } catch (deleteError) {
        setError(errorMessage(deleteError, 'Unable to delete the task.'));
        return false;
      }
    },
    [api, refreshTasks]
  );

  const handleToggleTaskCompletion = useCallback(
    async (task: DesktopTask) => {
      setError(null);
      setStatus(null);
      try {
        const nextStatus = task.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED';
        await api.updateTask(task.id, { status: nextStatus });
        await refreshTasks();
        setStatus(nextStatus === 'COMPLETED' ? 'Task completed.' : 'Task reopened.');
        return true;
      } catch (toggleError) {
        setError(errorMessage(toggleError, 'Unable to update the task status.'));
        return false;
      }
    },
    [api, refreshTasks]
  );

  return (
    <>
      {status ? (
        <p
          role="status"
          style={{
            margin: '0 0 16px',
            color: 'var(--calm-green)',
            fontSize: 13,
            fontWeight: 600,
          }}
        >
          {status}
        </p>
      ) : null}
      {error ? (
        <p
          role="alert"
          style={{
            margin: '0 0 16px',
            color: 'var(--calm-red, #b42318)',
            fontSize: 13,
            fontWeight: 600,
          }}
        >
          {error}
        </p>
      ) : null}
      <TasksScreen
        overdueTasks={buckets.overdue}
        todayTasks={buckets.today}
        thisWeekTasks={buckets.thisWeek}
        unscheduledTasks={buckets.unscheduled}
        completedTasks={buckets.completed}
        loading={loading}
        createSignal={createSignal}
        onCreateTask={handleCreateTask}
        onUpdateTask={handleUpdateTask}
        onDeleteTask={handleDeleteTask}
        onToggleTaskCompletion={handleToggleTaskCompletion}
      />
    </>
  );
}

export default TasksSurface;

