import { CalmCard, CalmOverline } from './calm';
import { formatEventMeta } from './events/eventFormat';
import type { DesktopEvent, DesktopTask } from '../lib/api';

type EventAnchor = 'START' | 'END';

interface LinkEventInput {
  event_id: string;
  anchor?: EventAnchor;
  offset_minutes?: number | null;
}

export type DesktopTaskFilter = 'open' | 'today' | 'this_week' | 'completed';

const TEXT = {
  muted: 'var(--calm-ink3)',
  secondary: 'var(--calm-ink2)',
  primary: 'var(--calm-ink)',
};

interface TaskFormState {
  title: string;
  notes: string;
  dueAt: string;
  dueWindowStartAt: string;
  dueWindowEndAt: string;
  medicationName: string;
  dosageText: string;
