    },
    quiet: {
      background: 'transparent',
      borderColor: 'transparent',
      color: TEXT.secondary,
    },
  };

  return (
    <button
      {...props}
      disabled={disabled}
      style={{
        height: compact ? 32 : 38,
        minWidth: compact ? 0 : 92,
        padding: compact ? '0 11px' : '0 16px',
        borderRadius: 99,
        border: '1px solid',
        fontFamily: 'var(--calm-sans)',
        fontSize: compact ? 12.5 : 13.5,
