    linkOffsetMinutes: '',
  };
}

function isTaskSeriesObject(
  value: DesktopTask['task_series']
): value is Exclude<DesktopTask['task_series'], string | null | undefined> {
  return Boolean(value && typeof value !== 'string');
}

function isMedicationTask(task: DesktopTask): boolean {
  return task.task_kind === 'MEDICATION' || isTaskSeriesObject(task.task_series);
}

function formFromTask(task: DesktopTask): TaskFormState {
  const series = isTaskSeriesObject(task.task_series) ? task.task_series : null;
  return {
    title: task.title,
    notes: task.notes ?? '',
    dueAt: toDateTimeLocalValue(task.due_at ?? null),
    dueWindowStartAt: toDateTimeLocalValue(task.due_window_start_at ?? null),
    dueWindowEndAt: toDateTimeLocalValue(task.due_window_end_at ?? null),
    medicationName: series?.medication_name ?? '',
    dosageText: series?.dosage_text ?? '',
    instructions: series?.instructions ?? '',
    minIntervalHours: series?.min_interval_hours ? String(series.min_interval_hours) : '',
    maxIntervalHours: series?.max_interval_hours ? String(series.max_interval_hours) : '',
    isAsNeeded: Boolean(series?.is_as_needed),
    seriesIsActive: series?.is_active ?? true,
    remindersEnabled: task.reminders?.some((reminder) => !reminder.sent_at) ?? false,
    linkedEventId: task.linked_event?.id ?? '',
    linkAnchor: task.linked_event_anchor === 'START' ? 'START' : 'END',
    linkOffsetMinutes:
