  onToggleTaskCompletion,
  runTaskAction,
}: TaskSectionProps) {
  return (
    <CalmCard style={{ padding: 0, overflow: 'hidden' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
          padding: '16px 18px',
