            fontSize: 13,
            fontWeight: 700,
          }}
        >
          {tasks.length}
        </span>
      </div>

      {tasks.length === 0 && emptyText ? <EmptyState>{emptyText}</EmptyState> : null}

      {tasks.map((task) => (
        <TaskRow
          key={task.id}
          task={task}
