                {task.notes}
              </p>
            ) : null}
          </>
        )}
      </div>

      {!isEditing ? (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            paddingTop: 1,
          }}
        >
          <ActionButton
            type="button"
            compact
            tone="quiet"
            aria-label={`Edit ${task.title}`}
            onClick={() => onEditTask(task)}
            disabled={isBusy}
          >
            Edit
