  }

  return date.toISOString();
}

function parseOptionalPositiveInt(value: string, label: string): number | null {
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  const parsed = Number(trimmed);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new Error(`${label} must be a positive whole number.`);
  }
  return parsed;
}

const OFFSET_LIMIT = 525600; // ±1 year in minutes; matches the backend bounds.

function parseOptionalSignedInt(value: string, label: string): number | null {
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  const parsed = Number(trimmed);
  if (!Number.isInteger(parsed) || Math.abs(parsed) > OFFSET_LIMIT) {
    throw new Error(`${label} must be a whole number of minutes.`);
  }
  return parsed;
}

function formatDateTime(value: string): string {
  try {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    }).format(new Date(value));
  } catch {
    return value;
  }
}

function dueLabel(task: DesktopTask, completed: boolean): string | null {
  if (completed && task.completed_at) {
    return `Completed ${formatDateTime(task.completed_at)}`;
  }
  if (task.due_at) {
    return `Due ${formatDateTime(task.due_at)}`;
  }
  if (task.due_window_end_at) {
    return `By ${formatDateTime(task.due_window_end_at)}`;
  }
  return null;
}

function assigneeLabel(task: DesktopTask): string | null {
  const person = task.assigned_to;
  if (!person) {
    return null;
  }

  return person.display_name || person.full_name || person.first_name || null;
}

function taskKindLabel(task: DesktopTask): string | null {
  const kind = task.task_kind;
  if (!kind || kind === 'MANUAL') {
    return null;
  }

  return kind
    .split(/[_\s-]+/)
    .filter(Boolean)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1).toLowerCase()}`)
    .join(' ');
}

