};

interface TaskRowProps {
  task: DesktopTask;
  completed: boolean;
  isEditing: boolean;
  editForm: TaskFormState;
  isBusy: boolean;
  onEditTask(task: DesktopTask): void;
  onChangeEditForm(form: TaskFormState): void;
  onCancelEdit(): void;
  onUpdateTask(taskId: string, input: TaskUpdateInput): Promise<boolean>;
  onDeleteTask(taskId: string): Promise<boolean>;
  onToggleTaskCompletion(task: DesktopTask): Promise<boolean>;
  runTaskAction(taskId: string, action: () => Promise<boolean>): void;
}

function TaskRow({
  task,
  completed,
  isEditing,
  editForm,
  isBusy,
  onEditTask,
  onChangeEditForm,
  onCancelEdit,
  onUpdateTask,
  onDeleteTask,
  onToggleTaskCompletion,
  runTaskAction,
}: TaskRowProps) {
  const meta = [dueLabel(task, completed), assigneeLabel(task), taskKindLabel(task)].filter(
    Boolean
  );

  return (
    <article
      style={{
        display: 'grid',
        gridTemplateColumns: '34px minmax(0, 1fr) auto',
        gap: 14,
        alignItems: 'start',
        padding: '16px 18px',
        borderTop: '1px solid var(--calm-line)',
      }}
    >
      <button
        type="button"
        aria-label={completed ? `Reopen ${task.title}` : `Mark ${task.title} complete`}
        onClick={() => {
          runTaskAction(task.id, () => onToggleTaskCompletion(task));
        }}
        disabled={isBusy}
        style={{
          width: 30,
          height: 30,
          borderRadius: 99,
          border: '1px solid var(--calm-line)',
          background: completed ? '#d1fae5' : 'var(--calm-page)',
          color: completed ? '#047857' : TEXT.secondary,
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: 15,
          fontWeight: 700,
          cursor: isBusy ? 'default' : 'pointer',
        }}
      >
        {completed ? '✓' : ''}
      </button>

      <div style={{ minWidth: 0 }}>
        {isEditing ? (
          <form
            onSubmit={(event) => {
              event.preventDefault();
              runTaskAction(task.id, async () => {
                const input: TaskUpdateInput = {
                  title: editForm.title.trim(),
                  notes: editForm.notes.trim(),
                  due_at: toIsoDateTime(editForm.dueAt),
                };
                if (isMedicationTask(task)) {
                  let minIntervalHours: number | null;
                  let maxIntervalHours: number | null;
                  try {
                    minIntervalHours = parseOptionalPositiveInt(
                      editForm.minIntervalHours,
                      'Minimum interval hours'
                    );
                    maxIntervalHours = parseOptionalPositiveInt(
                      editForm.maxIntervalHours,
                      'Maximum interval hours'
                    );
                  } catch (error) {
                    window.alert(
                      error instanceof Error ? error.message : 'Use valid interval hours.'
                    );
                    return false;
                  }
                  if (minIntervalHours && maxIntervalHours && maxIntervalHours < minIntervalHours) {
                    window.alert(
                      'Maximum interval hours must be greater than or equal to minimum interval hours.'
                    );
                    return false;
                  }
                  Object.assign(input, {
                    due_window_start_at: toIsoDateTime(editForm.dueWindowStartAt),
                    due_window_end_at: toIsoDateTime(editForm.dueWindowEndAt),
                    medication_name: editForm.medicationName.trim(),
                    dosage_text: editForm.dosageText.trim(),
                    instructions: editForm.instructions.trim(),
                    min_interval_hours: minIntervalHours,
                    max_interval_hours: maxIntervalHours,
                    is_as_needed: editForm.isAsNeeded,
                    series_is_active: editForm.seriesIsActive,
                    reminders_enabled: editForm.remindersEnabled,
                  });
                }
                const didUpdate = await onUpdateTask(task.id, input);
                if (didUpdate) {
                  onCancelEdit();
                }
                return didUpdate;
              });
            }}
            style={{
              display: 'grid',
              gap: 12,
              padding: 14,
              borderRadius: 14,
              background: 'var(--calm-page)',
              border: '1px solid var(--calm-line)',
            }}
          >
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'minmax(0, 1fr) minmax(190px, 240px)',
                gap: 12,
              }}
            >
              <Field label="Task title">
                <input
                  aria-label={`Edit title for ${task.title}`}
                  type="text"
                  value={editForm.title}
                  onChange={(event) =>
                    onChangeEditForm({
                      ...editForm,
                      title: event.target.value,
                    })
                  }
                  required
                  style={inputStyle}
                />
              </Field>
              <Field label="Due">
                <input
                  aria-label={`Edit due date for ${task.title}`}
                  type="datetime-local"
                  value={editForm.dueAt}
                  onChange={(event) =>
                    onChangeEditForm({
                      ...editForm,
                      dueAt: event.target.value,
                    })
                  }
                  style={inputStyle}
                />
              </Field>
            </div>
            <Field label="Notes">
              <textarea
                aria-label={`Edit notes for ${task.title}`}
                value={editForm.notes}
                onChange={(event) =>
                  onChangeEditForm({
                    ...editForm,
                    notes: event.target.value,
                  })
                }
                rows={3}
                style={{ ...inputStyle, resize: 'vertical' }}
              />
            </Field>
            {isMedicationTask(task) ? (
              <div
                data-testid="desktop-medication-task-fields"
                style={{
                  display: 'grid',
                  gap: 12,
                  padding: 12,
                  borderRadius: 12,
                  border: '1px solid var(--calm-line)',
                  background: 'var(--calm-card)',
                }}
              >
                <div
                  style={{
                    color: TEXT.primary,
                    fontSize: 14,
                    fontWeight: 650,
                    letterSpacing: 0,
                  }}
                >
                  Medication Schedule
                </div>
                <div
                  style={{
                    display: 'grid',
                    gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1fr)',
                    gap: 12,
                  }}
                >
                  <Field label="Medicine">
                    <input
                      aria-label={`Edit medicine for ${task.title}`}
                      type="text"
                      value={editForm.medicationName}
                      onChange={(event) =>
                        onChangeEditForm({
                          ...editForm,
                          medicationName: event.target.value,
                        })
                      }
                      style={inputStyle}
                    />
                  </Field>
                  <Field label="Dosage">
                    <input
                      aria-label={`Edit dosage for ${task.title}`}
                      type="text"
                      value={editForm.dosageText}
                      onChange={(event) =>
                        onChangeEditForm({
                          ...editForm,
                          dosageText: event.target.value,
                        })
                      }
                      style={inputStyle}
                    />
                  </Field>
                </div>
                <div
                  style={{
                    display: 'grid',
                    gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1fr)',
                    gap: 12,
                  }}
                >
                  <Field label="Window start">
                    <input
                      aria-label={`Edit window start for ${task.title}`}
                      type="datetime-local"
                      value={editForm.dueWindowStartAt}
                      onChange={(event) =>
                        onChangeEditForm({
                          ...editForm,
                          dueWindowStartAt: event.target.value,
                        })
                      }
                      style={inputStyle}
                    />
                  </Field>
                  <Field label="Window end">
                    <input
                      aria-label={`Edit window end for ${task.title}`}
                      type="datetime-local"
                      value={editForm.dueWindowEndAt}
                      onChange={(event) =>
                        onChangeEditForm({
                          ...editForm,
                          dueWindowEndAt: event.target.value,
                        })
                      }
                      style={inputStyle}
                    />
                  </Field>
                </div>
                <div
                  style={{
                    display: 'grid',
                    gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1fr)',
                    gap: 12,
                  }}
                >
                  <Field label="Minimum interval hours">
                    <input
                      aria-label={`Edit minimum interval for ${task.title}`}
                      type="number"
                      min="1"
                      value={editForm.minIntervalHours}
                      onChange={(event) =>
                        onChangeEditForm({
                          ...editForm,
                          minIntervalHours: event.target.value,
                        })
                      }
                      style={inputStyle}
                    />
                  </Field>
                  <Field label="Maximum interval hours">
                    <input
                      aria-label={`Edit maximum interval for ${task.title}`}
                      type="number"
                      min="1"
                      value={editForm.maxIntervalHours}
                      onChange={(event) =>
                        onChangeEditForm({
                          ...editForm,
                          maxIntervalHours: event.target.value,
                        })
                      }
                      style={inputStyle}
                    />
                  </Field>
                </div>
                <Field label="Instructions">
                  <textarea
                    aria-label={`Edit medication instructions for ${task.title}`}
                    value={editForm.instructions}
                    onChange={(event) =>
                      onChangeEditForm({
                        ...editForm,
                        instructions: event.target.value,
                      })
                    }
                    rows={3}
                    style={{ ...inputStyle, resize: 'vertical' }}
                  />
                </Field>
                <div
                  style={{
                    display: 'flex',
                    flexWrap: 'wrap',
                    gap: 14,
                  }}
                >
                  {[
                    ['isAsNeeded', 'As needed'],
                    ['seriesIsActive', 'Active schedule'],
                    ['remindersEnabled', 'Reminder enabled'],
                  ].map(([key, label]) => {
                    const formKey = key as 'isAsNeeded' | 'seriesIsActive' | 'remindersEnabled';
                    return (
                      <label
                        key={key}
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 7,
                          color: TEXT.secondary,
                          fontSize: 13,
                          fontWeight: 600,
                        }}
                      >
                        <input
                          type="checkbox"
                          checked={editForm[formKey]}
                          onChange={(event) =>
                            onChangeEditForm({
                              ...editForm,
                              [formKey]: event.target.checked,
                            })
                          }
                        />
                        {label}
                      </label>
                    );
                  })}
                </div>
              </div>
            ) : null}
            <div style={formActionsStyle}>
              <ActionButton type="button" compact onClick={onCancelEdit} disabled={isBusy}>
                Cancel
              </ActionButton>
              <ActionButton tone="primary" compact type="submit" disabled={isBusy}>
                {isBusy ? 'Saving...' : 'Save'}
              </ActionButton>
            </div>
          </form>
        ) : (
          <>
            <h3
              style={{
                margin: 0,
                color: completed ? TEXT.secondary : TEXT.primary,
                fontSize: 15.5,
                lineHeight: 1.28,
                fontWeight: completed ? 500 : 650,
                letterSpacing: 0,
                textDecoration: completed ? 'line-through' : 'none',
              }}
            >
              {task.title}
            </h3>
            {meta.length > 0 ? (
              <div
                style={{
                  display: 'flex',
                  flexWrap: 'wrap',
                  gap: '4px 14px',
                  marginTop: 7,
                  color: TEXT.secondary,
                  fontSize: 13,
                  lineHeight: 1.35,
                }}
              >
                {meta.map((item) => (
                  <span key={item}>{item}</span>
                ))}
              </div>
            ) : null}
            {task.notes ? (
              <p
                style={{
                  margin: '9px 0 0',
                  color: TEXT.secondary,
                  fontSize: 14,
                  lineHeight: 1.45,
                }}
              >
                {task.notes}
              </p>
            ) : null}
          </>
        )}
      </div>

      {!isEditing ? (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            paddingTop: 1,
          }}
        >
          <ActionButton
            type="button"
            compact
            tone="quiet"
            aria-label={`Edit ${task.title}`}
            onClick={() => onEditTask(task)}
            disabled={isBusy}
          >
            Edit
          </ActionButton>
          <ActionButton
            type="button"
            compact
            tone="danger"
            aria-label={`Delete ${task.title}`}
            onClick={() => {
              runTaskAction(task.id, () => onDeleteTask(task.id));
            }}
            disabled={isBusy}
          >
            {isBusy ? 'Working...' : 'Delete'}
          </ActionButton>
        </div>
      ) : null}
    </article>
  );
}

interface TasksScreenProps {
  overdueTasks: DesktopTask[];
  todayTasks: DesktopTask[];
  thisWeekTasks: DesktopTask[];
  unscheduledTasks: DesktopTask[];
  completedTasks: DesktopTask[];
  loading: boolean;
  createSignal?: number;
  onCreateTask(input: {
    title: string;
    notes?: string;
    due_at?: string | null;
  }): Promise<boolean>;
  onUpdateTask(taskId: string, input: TaskUpdateInput): Promise<boolean>;
  onDeleteTask(taskId: string): Promise<boolean>;
  onToggleTaskCompletion(task: DesktopTask): Promise<boolean>;
}

export function TasksScreen({
  overdueTasks,
  todayTasks,
  thisWeekTasks,
  unscheduledTasks,
  completedTasks,
  loading,
  createSignal = 0,
  onCreateTask,
  onUpdateTask,
  onDeleteTask,
  onToggleTaskCompletion,
}: TasksScreenProps) {
  const [isCreatingTask, setIsCreatingTask] = useState(false);
  const [createForm, setCreateForm] = useState<TaskFormState>(emptyTaskForm());
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<TaskFormState>(emptyTaskForm());
  const [busyTaskId, setBusyTaskId] = useState<string | null>(null);
  const [creatingTask, setCreatingTask] = useState(false);

  useEffect(() => {
    if (createSignal <= 0) return;
    setCreateForm(emptyTaskForm());
    setIsCreatingTask(true);
  }, [createSignal]);

  const allVisibleTasks = [
    ...overdueTasks,
    ...todayTasks,
    ...thisWeekTasks,
    ...unscheduledTasks,
    ...completedTasks,
  ];

  useEffect(() => {
    if (editingTaskId && !allVisibleTasks.some((task) => task.id === editingTaskId)) {
      setEditingTaskId(null);
      setEditForm(emptyTaskForm());
    }
  }, [allVisibleTasks, editingTaskId]);

  async function handleCreateTask(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!createForm.title.trim()) {
      return;
    }

    setCreatingTask(true);
    const didCreate = await onCreateTask({
      title: createForm.title.trim(),
      notes: createForm.notes.trim(),
      due_at: toIsoDateTime(createForm.dueAt),
    }).catch(() => false);
    setCreatingTask(false);

    if (!didCreate) {
      return;
    }

    setCreateForm(emptyTaskForm());
    setIsCreatingTask(false);
  }

  function runTaskAction(taskId: string, action: () => Promise<boolean>) {
    setBusyTaskId(taskId);
    void action()
      .catch(() => false)
      .finally(() => setBusyTaskId(null));
  }

  const sharedSectionProps = {
    editingTaskId,
    editForm,
    busyTaskId,
    onEditTask: (task: DesktopTask) => {
      setEditingTaskId(task.id);
      setEditForm(formFromTask(task));
    },
    onChangeEditForm: setEditForm,
    onCancelEdit: () => {
      setEditingTaskId(null);
      setEditForm(emptyTaskForm());
    },
    onUpdateTask,
    onDeleteTask,
    onToggleTaskCompletion,
    runTaskAction,
  };

  return (
    <section
      data-testid="tasks-screen"
      aria-label="Tasks"
      style={{
        display: 'grid',
        gap: 22,
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          gap: 18,
        }}
      >
        <div>
          <CalmOverline>Tasks</CalmOverline>
          <h1
            style={{
              margin: '8px 0 0',
              fontSize: 30,
              lineHeight: 1.1,
              fontWeight: 650,
              color: TEXT.primary,
              letterSpacing: 0,
            }}
          >
