interface TasksScreenProps {
  overdueTasks: DesktopTask[];
  todayTasks: DesktopTask[];
  thisWeekTasks: DesktopTask[];
  unscheduledTasks: DesktopTask[];
  completedTasks: DesktopTask[];
  loading: boolean;
  createSignal?: number;
  onCreateTask(input: {
    title: string;
    notes?: string;
    due_at?: string | null;
  }): Promise<boolean>;
  onUpdateTask(taskId: string, input: TaskUpdateInput): Promise<boolean>;
  onDeleteTask(taskId: string): Promise<boolean>;
  onToggleTaskCompletion(task: DesktopTask): Promise<boolean>;
}

export function TasksScreen({
  overdueTasks,
  todayTasks,
  thisWeekTasks,
  unscheduledTasks,
  completedTasks,
  loading,
  createSignal = 0,
  onCreateTask,
  onUpdateTask,
  onDeleteTask,
  onToggleTaskCompletion,
}: TasksScreenProps) {
  const [isCreatingTask, setIsCreatingTask] = useState(false);
  const [createForm, setCreateForm] = useState<TaskFormState>(emptyTaskForm());
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<TaskFormState>(emptyTaskForm());
  const [busyTaskId, setBusyTaskId] = useState<string | null>(null);
  const [creatingTask, setCreatingTask] = useState(false);

  useEffect(() => {
    if (createSignal <= 0) return;
    setCreateForm(emptyTaskForm());
    setIsCreatingTask(true);
  }, [createSignal]);

  const allVisibleTasks = [
    ...overdueTasks,
    ...todayTasks,
    ...thisWeekTasks,
    ...unscheduledTasks,
    ...completedTasks,
  ];

  useEffect(() => {
    if (editingTaskId && !allVisibleTasks.some((task) => task.id === editingTaskId)) {
      setEditingTaskId(null);
      setEditForm(emptyTaskForm());
    }
  }, [allVisibleTasks, editingTaskId]);

  async function handleCreateTask(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!createForm.title.trim()) {
      return;
    }

    setCreatingTask(true);
    const didCreate = await onCreateTask({
      title: createForm.title.trim(),
      notes: createForm.notes.trim(),
      due_at: toIsoDateTime(createForm.dueAt),
    }).catch(() => false);
    setCreatingTask(false);

    if (!didCreate) {
      return;
    }

    setCreateForm(emptyTaskForm());
    setIsCreatingTask(false);
  }

  function runTaskAction(taskId: string, action: () => Promise<boolean>) {
    setBusyTaskId(taskId);
    void action()
      .catch(() => false)
      .finally(() => setBusyTaskId(null));
  }

  const sharedSectionProps = {
    editingTaskId,
    editForm,
    busyTaskId,
    onEditTask: (task: DesktopTask) => {
      setEditingTaskId(task.id);
      setEditForm(formFromTask(task));
    },
    onChangeEditForm: setEditForm,
    onCancelEdit: () => {
      setEditingTaskId(null);
      setEditForm(emptyTaskForm());
    },
    onUpdateTask,
    onDeleteTask,
    onToggleTaskCompletion,
    runTaskAction,
  };

  return (
    <section
      data-testid="tasks-screen"
      aria-label="Tasks"
      style={{
        display: 'grid',
        gap: 22,
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          gap: 18,
        }}
      >
        <div>
          <CalmOverline>Tasks</CalmOverline>
          <h1
            style={{
              margin: '8px 0 0',
              fontSize: 30,
              lineHeight: 1.1,
              fontWeight: 650,
              color: TEXT.primary,
              letterSpacing: 0,
            }}
          >
            Tasks
          </h1>
          <div
            style={{
              marginTop: 8,
              color: TEXT.secondary,
              fontSize: 14,
              lineHeight: 1.45,
            }}
          >
            Family to-dos across overdue, today, this week, and unscheduled.
          </div>
        </div>

        <ActionButton
          type="button"
          tone="primary"
          onClick={() => {
            setIsCreatingTask((current) => !current);
            setCreateForm(emptyTaskForm());
          }}
        >
          {isCreatingTask ? 'Close' : '+ Add Task'}
        </ActionButton>
      </div>

      {isCreatingTask ? (
        <CalmCard>
          <form
            onSubmit={handleCreateTask}
            style={{
              display: 'grid',
              gap: 12,
            }}
          >
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'minmax(0, 1fr) minmax(190px, 240px)',
                gap: 12,
              }}
            >
              <Field label="Task title">
                <input
                  aria-label="New task title"
                  type="text"
                  value={createForm.title}
                  onChange={(event) =>
                    setCreateForm((current) => ({
                      ...current,
                      title: event.target.value,
                    }))
                  }
                  placeholder="Pick up dry cleaning"
                  required
                  style={inputStyle}
                />
              </Field>
              <Field label="Due">
                <input
                  aria-label="New task due date"
                  type="datetime-local"
                  value={createForm.dueAt}
                  onChange={(event) =>
                    setCreateForm((current) => ({
                      ...current,
                      dueAt: event.target.value,
                    }))
                  }
                  style={inputStyle}
                />
              </Field>
            </div>
            <Field label="Notes">
              <textarea
                aria-label="New task notes"
                value={createForm.notes}
                onChange={(event) =>
                  setCreateForm((current) => ({
                    ...current,
                    notes: event.target.value,
                  }))
                }
                placeholder="Add any context the household needs."
                rows={3}
                style={{ ...inputStyle, resize: 'vertical' }}
              />
            </Field>
            <div style={formActionsStyle}>
              <ActionButton
                type="button"
                compact
                onClick={() => setIsCreatingTask(false)}
                disabled={creatingTask}
              >
                Cancel
              </ActionButton>
              <ActionButton tone="primary" compact type="submit" disabled={creatingTask}>
                {creatingTask ? 'Creating...' : 'Create'}
              </ActionButton>
            </div>
          </form>
        </CalmCard>
      ) : null}

      {loading && allVisibleTasks.length === 0 ? (
        <CalmCard>
          <EmptyState>Loading tasks...</EmptyState>
        </CalmCard>
      ) : null}

      <TaskSection
        title="Overdue"
        tone="danger"
        tasks={overdueTasks}
        emptyText="Nothing overdue. Nice work."
        {...sharedSectionProps}
      />
      <TaskSection
        title="Today"
        tasks={todayTasks}
        emptyText="Nothing due today."
        {...sharedSectionProps}
      />
      <TaskSection
        title="This Week"
        tasks={thisWeekTasks}
        emptyText="Nothing scheduled this week."
        {...sharedSectionProps}
      />
      {unscheduledTasks.length > 0 ? (
        <TaskSection title="Unscheduled" tasks={unscheduledTasks} {...sharedSectionProps} />
      ) : null}
      {completedTasks.length > 0 ? (
        <TaskSection
          title="Recently Completed"
          tasks={completedTasks}
          completed
          {...sharedSectionProps}
        />
      ) : null}
    </section>
  );
}
