function TaskRow({
  task,
  completed,
  isEditing,
  editForm,
  isBusy,
  linkableEvents,
  onEditTask,
  onChangeEditForm,
  onCancelEdit,
  onUpdateTask,
  onDeleteTask,
  onToggleTaskCompletion,
  onLinkTaskToEvent,
  onUnlinkTaskFromEvent,
  runTaskAction,
}: TaskRowProps) {
  const linkedEventLabel = task.linked_event
    ? `From event · ${task.linked_event.title}`
    : null;
  const meta = [
    dueLabel(task, completed),
    assigneeLabel(task),
    taskKindLabel(task),
    linkedEventLabel,
  ].filter(Boolean);

  return (
    <article
      style={{
        display: 'grid',
        gridTemplateColumns: '34px minmax(0, 1fr) auto',
