                  const desiredOffset = offsetMinutes ?? 0;
                  const unchanged =
                    currentEventId === selectedEventId &&
                    (task.linked_event_anchor ?? '') === editForm.linkAnchor &&
                    (task.linked_event_offset_minutes ?? 0) === desiredOffset;
                  if (!unchanged) {
                    const didLink = await onLinkTaskToEvent(task.id, {
                      event_id: selectedEventId,
                      anchor: editForm.linkAnchor,
                      offset_minutes: offsetMinutes,
                    });
                    if (!didLink) {
                      return false;
                    }
                  }
                }

                onCancelEdit();
                return true;
              });
