interface TaskSectionProps {
  title: string;
  tone?: 'danger' | 'neutral';
  emptyText?: string;
  tasks: DesktopTask[];
  completed?: boolean;
  editingTaskId: string | null;
  editForm: TaskFormState;
  busyTaskId: string | null;
  linkableEvents: DesktopEvent[];
  onEditTask(task: DesktopTask): void;
  onChangeEditForm(form: TaskFormState): void;
  onCancelEdit(): void;
  onUpdateTask(taskId: string, input: TaskUpdateInput): Promise<boolean>;
  onDeleteTask(taskId: string): Promise<boolean>;
  onToggleTaskCompletion(task: DesktopTask): Promise<boolean>;
  onLinkTaskToEvent(taskId: string, input: LinkEventInput): Promise<boolean>;
  onUnlinkTaskFromEvent(taskId: string): Promise<boolean>;
  runTaskAction(taskId: string, action: () => Promise<boolean>): void;
}

function TaskSection({
  title,
  tone = 'neutral',
  emptyText,
  tasks,
  completed = false,
  editingTaskId,
  editForm,
  busyTaskId,
  linkableEvents,
  onEditTask,
  onChangeEditForm,
  onCancelEdit,
  onUpdateTask,
  onDeleteTask,
  onToggleTaskCompletion,
  onLinkTaskToEvent,
  onUnlinkTaskFromEvent,
  runTaskAction,
}: TaskSectionProps) {
  return (
    <CalmCard style={{ padding: 0, overflow: 'hidden' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
          padding: '16px 18px',
          borderBottom: '1px solid var(--calm-line)',
        }}
      >
        <h2
          style={{
            margin: 0,
            color: tone === 'danger' ? 'var(--calm-peach-deep)' : TEXT.primary,
            fontSize: 18,
            lineHeight: 1.2,
            fontWeight: 650,
            letterSpacing: 0,
          }}
        >
          {title}
        </h2>
        <span
          aria-label={`${title} count`}
          style={{
            minWidth: 30,
            height: 30,
            borderRadius: 99,
            padding: '0 10px',
            display: 'inline-flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: tone === 'danger' ? '#fee2e2' : 'var(--calm-page)',
            color: tone === 'danger' ? '#991b1b' : TEXT.secondary,
            fontSize: 13,
            fontWeight: 700,
          }}
        >
          {tasks.length}
        </span>
      </div>

      {tasks.length === 0 && emptyText ? <EmptyState>{emptyText}</EmptyState> : null}

      {tasks.map((task) => (
        <TaskRow
          key={task.id}
          task={task}
          completed={completed || task.status === 'COMPLETED'}
          isEditing={editingTaskId === task.id}
          editForm={editForm}
          isBusy={busyTaskId === task.id}
          linkableEvents={linkableEvents}
          onEditTask={onEditTask}
          onChangeEditForm={onChangeEditForm}
          onCancelEdit={onCancelEdit}
          onUpdateTask={onUpdateTask}
          onDeleteTask={onDeleteTask}
          onToggleTaskCompletion={onToggleTaskCompletion}
