type TaskUpdateInput = {
  title?: string;
  notes?: string;
  due_at?: string | null;
  due_window_start_at?: string | null;
  due_window_end_at?: string | null;
  status?: string;
  medication_name?: string;
  dosage_text?: string;
  instructions?: string;
  min_interval_hours?: number | null;
  max_interval_hours?: number | null;
  is_as_needed?: boolean;
  series_is_active?: boolean;
  reminders_enabled?: boolean;
};

interface TaskRowProps {
  task: DesktopTask;
  completed: boolean;
  isEditing: boolean;
  editForm: TaskFormState;
  isBusy: boolean;
  linkableEvents: DesktopEvent[];
  onEditTask(task: DesktopTask): void;
  onChangeEditForm(form: TaskFormState): void;
  onCancelEdit(): void;
  onUpdateTask(taskId: string, input: TaskUpdateInput): Promise<boolean>;
  onDeleteTask(taskId: string): Promise<boolean>;
  onToggleTaskCompletion(task: DesktopTask): Promise<boolean>;
  onLinkTaskToEvent(taskId: string, input: LinkEventInput): Promise<boolean>;
  onUnlinkTaskFromEvent(taskId: string): Promise<boolean>;
  runTaskAction(taskId: string, action: () => Promise<boolean>): void;
}

function TaskRow({
  task,
  completed,
  isEditing,
  editForm,
  isBusy,
  linkableEvents,
  onEditTask,
  onChangeEditForm,
  onCancelEdit,
  onUpdateTask,
  onDeleteTask,
  onToggleTaskCompletion,
  onLinkTaskToEvent,
  onUnlinkTaskFromEvent,
  runTaskAction,
}: TaskRowProps) {
  const linkedEventLabel = task.linked_event
    ? `From event · ${task.linked_event.title}`
    : null;
  const meta = [
    dueLabel(task, completed),
    assigneeLabel(task),
    taskKindLabel(task),
    linkedEventLabel,
  ].filter(Boolean);

  return (
    <article
      style={{
        display: 'grid',
        gridTemplateColumns: '34px minmax(0, 1fr) auto',
        gap: 14,
        alignItems: 'start',
        padding: '16px 18px',
        borderTop: '1px solid var(--calm-line)',
      }}
    >
      <button
        type="button"
        aria-label={completed ? `Reopen ${task.title}` : `Mark ${task.title} complete`}
        onClick={() => {
          runTaskAction(task.id, () => onToggleTaskCompletion(task));
        }}
        disabled={isBusy}
        style={{
          width: 30,
          height: 30,
          borderRadius: 99,
          border: '1px solid var(--calm-line)',
          background: completed ? '#d1fae5' : 'var(--calm-page)',
          color: completed ? '#047857' : TEXT.secondary,
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: 15,
          fontWeight: 700,
          cursor: isBusy ? 'default' : 'pointer',
        }}
      >
        {completed ? '✓' : ''}
      </button>

      <div style={{ minWidth: 0 }}>
        {isEditing ? (
          <form
            onSubmit={(event) => {
              event.preventDefault();
              runTaskAction(task.id, async () => {
                const input: TaskUpdateInput = {
                  title: editForm.title.trim(),
                  notes: editForm.notes.trim(),
                  due_at: toIsoDateTime(editForm.dueAt),
                };
                if (isMedicationTask(task)) {
                  let minIntervalHours: number | null;
                  let maxIntervalHours: number | null;
                  try {
                    minIntervalHours = parseOptionalPositiveInt(
                      editForm.minIntervalHours,
                      'Minimum interval hours'
                    );
                    maxIntervalHours = parseOptionalPositiveInt(
                      editForm.maxIntervalHours,
                      'Maximum interval hours'
                    );
                  } catch (error) {
                    window.alert(
                      error instanceof Error ? error.message : 'Use valid interval hours.'
                    );
                    return false;
                  }
                  if (minIntervalHours && maxIntervalHours && maxIntervalHours < minIntervalHours) {
                    window.alert(
                      'Maximum interval hours must be greater than or equal to minimum interval hours.'
                    );
                    return false;
                  }
                  Object.assign(input, {
                    due_window_start_at: toIsoDateTime(editForm.dueWindowStartAt),
                    due_window_end_at: toIsoDateTime(editForm.dueWindowEndAt),
                    medication_name: editForm.medicationName.trim(),
                    dosage_text: editForm.dosageText.trim(),
                    instructions: editForm.instructions.trim(),
                    min_interval_hours: minIntervalHours,
                    max_interval_hours: maxIntervalHours,
                    is_as_needed: editForm.isAsNeeded,
                    series_is_active: editForm.seriesIsActive,
                    reminders_enabled: editForm.remindersEnabled,
                  });
                }
                let offsetMinutes: number | null;
                try {
                  offsetMinutes = parseOptionalSignedInt(
                    editForm.linkOffsetMinutes,
                    'Reminder offset'
                  );
                } catch (error) {
                  window.alert(
                    error instanceof Error ? error.message : 'Use a valid reminder offset.'
                  );
                  return false;
                }

                const didUpdate = await onUpdateTask(task.id, input);
                if (!didUpdate) {
                  return false;
                }

                // Reconcile the event link via the dedicated endpoints (the
                // anchored link owns due_at + reminder; never the bare FK on
                // updateTask). Idempotent: skip when nothing changed so an
                // unrelated edit doesn't churn the reminder.
                const selectedEventId = editForm.linkedEventId;
                const currentEventId = task.linked_event?.id ?? '';
                if (!selectedEventId) {
                  if (currentEventId) {
                    const didUnlink = await onUnlinkTaskFromEvent(task.id);
                    if (!didUnlink) {
                      return false;
                    }
                  }
                } else {
                  const desiredOffset = offsetMinutes ?? 0;
                  const unchanged =
                    currentEventId === selectedEventId &&
                    (task.linked_event_anchor ?? '') === editForm.linkAnchor &&
                    (task.linked_event_offset_minutes ?? 0) === desiredOffset;
                  if (!unchanged) {
                    const didLink = await onLinkTaskToEvent(task.id, {
                      event_id: selectedEventId,
                      anchor: editForm.linkAnchor,
                      offset_minutes: offsetMinutes,
                    });
                    if (!didLink) {
                      return false;
                    }
                  }
                }

                onCancelEdit();
                return true;
              });
            }}
            style={{
              display: 'grid',
              gap: 12,
              padding: 14,
              borderRadius: 14,
              background: 'var(--calm-page)',
              border: '1px solid var(--calm-line)',
            }}
          >
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'minmax(0, 1fr) minmax(190px, 240px)',
                gap: 12,
              }}
            >
              <Field label="Task title">
                <input
                  aria-label={`Edit title for ${task.title}`}
                  type="text"
                  value={editForm.title}
                  onChange={(event) =>
                    onChangeEditForm({
                      ...editForm,
                      title: event.target.value,
                    })
                  }
                  required
                  style={inputStyle}
                />
              </Field>
              <Field label="Due">
                <input
                  aria-label={`Edit due date for ${task.title}`}
                  type="datetime-local"
                  value={editForm.dueAt}
                  onChange={(event) =>
                    onChangeEditForm({
                      ...editForm,
                      dueAt: event.target.value,
                    })
                  }
                  style={inputStyle}
                />
              </Field>
            </div>
            <Field label="Notes">
              <textarea
                aria-label={`Edit notes for ${task.title}`}
                value={editForm.notes}
                onChange={(event) =>
                  onChangeEditForm({
                    ...editForm,
                    notes: event.target.value,
                  })
                }
                rows={3}
                style={{ ...inputStyle, resize: 'vertical' }}
              />
            </Field>
            <div
              data-testid="desktop-linked-event-fields"
              style={{
                display: 'grid',
                gap: 12,
                padding: 12,
                borderRadius: 12,
                border: '1px solid var(--calm-line)',
                background: 'var(--calm-card)',
              }}
            >
              <div
                style={{
                  color: TEXT.primary,
                  fontSize: 14,
                  fontWeight: 650,
                  letterSpacing: 0,
                }}
              >
                Linked Event
              </div>
              <div style={{ color: TEXT.muted, fontSize: 12, lineHeight: 1.4 }}>
                Link this task to an event to set its due date from the event. The reminder
                fires relative to that event time.
              </div>
              <Field label="Event">
                <select
                  aria-label={`Edit linked event for ${task.title}`}
                  value={editForm.linkedEventId}
                  onChange={(event) =>
                    onChangeEditForm({
                      ...editForm,
                      linkedEventId: event.target.value,
                    })
                  }
                  style={inputStyle}
                >
                  <option value="">No linked event</option>
                  {task.linked_event &&
                  !linkableEvents.some((event) => event.id === task.linked_event?.id) ? (
                    <option value={task.linked_event.id}>
                      {task.linked_event.title} (currently linked)
                    </option>
                  ) : null}
