import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';

import { TasksScreen } from '../TasksScreen';
import type { DesktopTask } from '../../lib/api';

const MEDICATION_TASK: DesktopTask = {
  id: 'task-med-1',
  title: 'Give Trazodone to Alice',
  notes: 'Give with a snack.',
  status: 'PENDING',
  task_kind: 'MEDICATION',
  due_window_start_at: '2026-05-25T12:00:00.000Z',
  due_at: '2026-05-25T14:00:00.000Z',
  due_window_end_at: '2026-05-25T16:00:00.000Z',
  task_series: {
    id: 'series-1',
    medication_name: 'Trazodone',
    dosage_text: '100mg',
    instructions: 'Give every 8 to 12 hours as needed.',
    min_interval_hours: 8,
    max_interval_hours: 12,
    is_as_needed: true,
    is_active: true,
  },
  reminders: [
    {
      id: 'reminder-1',
      kind: 'WINDOW_OPEN',
      remind_at: '2026-05-25T12:00:00.000Z',
      sent_at: null,
    },
  ],
};

function renderTasksScreen(overrides: Partial<Parameters<typeof TasksScreen>[0]> = {}) {
  return render(
    <TasksScreen
      overdueTasks={[]}
      todayTasks={[MEDICATION_TASK]}
      thisWeekTasks={[]}
      unscheduledTasks={[]}
      completedTasks={[]}
      loading={false}
      onCreateTask={vi.fn().mockResolvedValue(true)}
      onUpdateTask={vi.fn().mockResolvedValue(true)}
      onDeleteTask={vi.fn().mockResolvedValue(true)}
      onToggleTaskCompletion={vi.fn().mockResolvedValue(true)}
      {...overrides}
    />
  );
}

describe('TasksScreen', () => {
  it('renders and saves medication task fields for matching tasks', async () => {
    const onUpdateTask = vi.fn().mockResolvedValue(true);
    renderTasksScreen({ onUpdateTask });

    fireEvent.click(screen.getByRole('button', { name: 'Edit Give Trazodone to Alice' }));

    expect(screen.getByTestId('desktop-medication-task-fields')).toBeInTheDocument();
    expect(screen.getByLabelText('Edit medicine for Give Trazodone to Alice')).toHaveValue(
      'Trazodone'
    );

    fireEvent.change(screen.getByLabelText('Edit dosage for Give Trazodone to Alice'), {
      target: { value: '75mg' },
    });
    fireEvent.change(screen.getByLabelText('Edit maximum interval for Give Trazodone to Alice'), {
      target: { value: '10' },
    });
    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    await waitFor(() => expect(onUpdateTask).toHaveBeenCalled());
    expect(onUpdateTask).toHaveBeenCalledWith(
      'task-med-1',
      expect.objectContaining({
        medication_name: 'Trazodone',
        dosage_text: '75mg',
        instructions: 'Give every 8 to 12 hours as needed.',
        min_interval_hours: 8,
        max_interval_hours: 10,
        is_as_needed: true,
        series_is_active: true,
        reminders_enabled: true,
        due_window_start_at: expect.any(String),
        due_window_end_at: expect.any(String),
      })
    );
  });
});

